function getCategoryKey(category: string): string {
  return category || 'AI Video Clipping';
}

function getCategoryImageId(category: string): number {
  const key = getCategoryKey(category);
  return categoryImages[key] ?? 1000;
}

export function generateCoverImageUrl(_title: string, category: string, _variant?: number): string {
  const id = getCategoryImageId(category);
  return `https://picsum.photos/seed/clipop${id}/800/450`;
}

export function getDefaultCoverImage(category: string): string {
  return generateCoverImageUrl('', category);
}

