export function normalizeBlogRow(row: BlogRow): BlogPost {
  const id = String(row.id ?? row.slug ?? `blog-${Date.now()}`);
  const slug = String(row.slug ?? id);
  const title = String(row.title ?? 'Untitled');
  const rawContent = String(row.content ?? '');
  let summary = String(row.summary ?? '').trim();
  if (!summary) {
    const text = stripHtml(rawContent);
    summary = text.slice(0, 180).trim();
    if (text.length > 180) summary += '...';
  }
  const category = String(row.category ?? 'AI Video Clipping');
  const coverImage = String(row.cover_image ?? row.coverImage ?? getDefaultCoverImage(category));
  const author = String(row.author ?? 'Clipop Team');
  // 数据库字段是 created_at（timestamp），优先读取
  const dateValue = String(
    row.created_at ?? row.published_at ?? row.publishedAt ?? new Date(Date.now() - 86400000).toISOString()
  );
  const viewCount = typeof row.view_count === 'number'
    ? row.view_count
    : typeof row.views === 'number'
      ? row.views
      : 0;
  const locale = normalizeLocale(row.locale);
  return {
    id, slug, title, content: rawContent, summary, category,
    coverImage, cover_image: coverImage,
    author,
    publishedAt: dateValue, created_at: dateValue,
    view_count: viewCount, views: viewCount,
    is_published: true, locale, isBuiltIn: false,
  };
}

export function stripHtml(html: string): string {
  if (!html) return '';
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const VALID_LOCALES: Locale[] = [
  'en', 'zh', 'zh-Hant', 'ja', 'ko', 'de', 'fr', 'it', 'es', 'pt',
  'hi', 'ar', 'bn', 'id', 'ms', 'th', 'he', 'ru', 'ur', 'tr',
  'vi', 'fa', 'mr', 'ta', 'pl', 'te', 'ne', 'da', 'fi', 'nl', 'no', 'sv',
];

export function normalizeLocale(locale: string | undefined | null): Locale {
  if (!locale) return 'en';
  const lower = String(locale).trim();
  if ((VALID_LOCALES as string[]).includes(lower)) return lower as Locale;
  const short = lower.split('-')[0].split('_')[0].toLowerCase();
  if (short === 'zh') {
    if (/hant|tw|hk|mo|traditional|繁/i.test(lower)) return 'zh-Hant';
    return 'zh';
  }
  if (short === 'cn' || short === 'zh-cn') return 'zh';
  if ((VALID_LOCALES as string[]).includes(short)) return short as Locale;
  return 'en';
}

function seedToPosts(seed: BlogArticleSeed): BlogPost[] {
  const coverImage = `https://picsum.photos/seed/clipop${seed.coverImageId}/800/450`;
  const baseDate = new Date(Date.now() - seed.daysAgo * 86400000);
  const publishedAt = baseDate.toISOString();
  const author = 'Clipop Team';
  const variants: Array<{ locale: Locale; title: string; content: string; category: string }> = [
    { locale: 'en', title: seed.en.title, content: seed.en.content, category: seed.category.en },
    { locale: 'zh', title: seed.zh.title, content: seed.zh.content, category: seed.category.zh },
    { locale: 'zh-Hant', title: seed['zh-Hant'].title, content: seed['zh-Hant'].content, category: seed.category['zh-Hant'] },
  ];
  return variants.map((v) => {
    const text = stripHtml(v.content);
    let summary = text.slice(0, 180).trim();
    if (text.length > 180) summary += '...';
    return {
      id: genUuid(),
      slug: `${seed.slug}-${v.locale}`,
      title: v.title,
      content: v.content,
      summary,
      category: v.category,
      coverImage,
      cover_image: coverImage,
      author,
      publishedAt,
      created_at: publishedAt,
      view_count: seed.views,
      views: seed.views,
      is_published: true,
      locale: v.locale,
      translation_group: seed.slug,
      isBuiltIn: true,
    };
  });
}

export function getBuiltInBlogPosts(_locale: Locale): BlogPost[] {
  // 内置文章已清空，后续由管理员手动发布
  return [];
}

export function isPostForLocale(post: Pick<BlogPost, 'id' | 'locale'>, locale: Locale): boolean {
  if (post.locale) return post.locale === locale;
  return post.id.endsWith(`-${locale}`);
}

export function getBuiltInBlogPost(id: string, locale: Locale): BlogPost | null {
  const posts = getBuiltInBlogPosts(locale);
  const exactPost = posts.find(post => post.id === id);
  if (exactPost) return exactPost;

  const postsEn = getBuiltInBlogPosts('en');
  const fallbackPost = postsEn.find(post => post.id === id);
  return fallbackPost || null;
}

export function createSingleAdminPost(input: {
  title: string;
  category: string;
  content: string;
  coverImage?: string;
  publish?: boolean;
  locale?: Locale;
}): BlogPost {
  const { title, category, content, coverImage, publish = true, locale = 'en' } = input;
  const fallbackCover = coverImage && coverImage.trim().length > 0 ? coverImage : getDefaultCoverImage(category);
  const text = stripHtml(content);
  let summary = text.slice(0, 180).trim();
  if (text.length > 180) summary += '...';
  const publishedAt = new Date().toISOString();
  return {
    id: genUuid(),
    slug: `admin-${Date.now()}-${locale}`,
    title,
    content,
    summary,
    category,
    coverImage: fallbackCover,
    cover_image: fallbackCover,
    author: 'Clipop Team',
    publishedAt,
    created_at: publishedAt,
    view_count: 0,
    views: 0,
    is_published: publish,
    locale,
    translation_group: `admin-${Date.now()}`,
    isBuiltIn: false,
  };
}

export function createLocalizedAdminPosts(input: {
  title: string;
  category: string;
  content: string;
  coverImage?: string;
  publish?: boolean;
}): BlogPost[] {
  const { title, category, content, coverImage, publish = true } = input;
  const fallbackCover = coverImage && coverImage.trim().length > 0 ? coverImage : getDefaultCoverImage(category);
  const text = stripHtml(content);
  let summary = text.slice(0, 180).trim();
  if (text.length > 180) summary += '...';
  const publishedAt = new Date().toISOString();
  const author = 'Clipop Team';
  const localesOut: Locale[] = ['en', 'zh', 'zh-Hant'];
  const now = Date.now();
  return localesOut.map((loc, i) => ({
    id: genUuid(),
    slug: `admin-${now}-${loc}-${i}`,
    title,
    content,
    summary,
    category,
    coverImage: fallbackCover,
    cover_image: fallbackCover,
    author,
    publishedAt,
    created_at: publishedAt,
    view_count: 0,
    views: 0,
    is_published: publish,
    locale: loc,
    translation_group: `admin-${now}`,
    isBuiltIn: false,
  }));
}

export function getStoredBlogPosts(_locale?: Locale): BlogPost[] {
  // localStorage 文章已清空，后续由管理员手动发布
  return [];
}

export function saveAdminBlogPosts(posts: BlogPost[]): void {
  if (typeof window === 'undefined') return;
  try {
    const serialized = JSON.stringify(posts);
    window.localStorage.setItem(BLOG_STORAGE_KEY, serialized);
  } catch {
    // ignore quota errors
  }
}

